// Package postgres implements the agent domain's execution store
// against PostgreSQL via jackc/pgx (ADR-0078, ADR-0080). The queries
// are generated by sqlc from queries.sql; the fence itself is the
// agent_execution_admit function migration 000029 declares.
package postgres

import (
	"context"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/internal/agent"
	"github.com/garamsh/garam/internal/agent/postgres/db"
	"github.com/garamsh/garam/internal/errorx"
	"github.com/garamsh/garam/internal/grn"
	"github.com/garamsh/garam/internal/pgxerr"
)

// Store implements agent.ExecutionStore.
type Store struct {
	pool *pgxpool.Pool
	q    *db.Queries
}

// Compile-time check that Store satisfies agent.ExecutionStore.
var _ agent.ExecutionStore = (*Store)(nil)

// New constructs a Postgres-backed execution store.
func New(pool *pgxpool.Pool) *Store {
	return &Store{pool: pool, q: db.New(pool)}
}

// inTx runs fn in one local transaction on one connection and commits
// what it wrote. fn calls nothing outside the transaction, so no lock
// it takes is held while another connection is awaited.
func (s *Store) inTx(ctx context.Context, op string, fn func(q *db.Queries) error) error {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return errorx.Wrap(err, op+": begin", errorx.KindUnavailable)
	}
	defer func() { _ = tx.Rollback(ctx) }()
	if err := fn(s.q.WithTx(tx)); err != nil {
		return err
	}
	if err := tx.Commit(ctx); err != nil {
		return errorx.Wrap(err, op+": commit", errorx.KindUnavailable)
	}
	return nil
}

// storageError classifies a driver error as pgxerr does, and reports a
// failure it cannot name as unavailable: a fence that storage did not
// answer is unknown, and unknown refuses.
func storageError(err error, op string, notFound, conflict error) error {
	err = pgxerr.Classify(err, op, notFound, conflict)
	if err != nil && errorx.KindOf(err) == errorx.KindUnknown {
		return errorx.Wrap(err, op, errorx.KindUnavailable)
	}
	return err
}

// lockExecution takes the agent's execution row FOR UPDATE. It is the
// first statement of every transaction that changes the execution.
func lockExecution(ctx context.Context, q *db.Queries, agentGRN grn.GRN) (db.AgentExecution, error) {
	row, err := q.LockExecution(ctx, agentGRN.String())
	if err != nil {
		return db.AgentExecution{}, storageError(err, "lock execution", agent.ErrAgentNotFound, nil)
	}
	return row, nil
}

// recheck confirms under the execution lock what the authority
// established before it: the assignee it covered still holds the agent,
// and its grant has not expired at this instant. It answers the epoch
// the agent is assigned at and that instant.
func recheck(ctx context.Context, q *db.Queries, agentGRN grn.GRN, authority agent.Lifecycle) (int, time.Time, error) {
	assignment, err := q.ShareAssignment(ctx, agentGRN.String())
	if err != nil {
		return 0, time.Time{}, storageError(err, "read assignment", agent.ErrNotAssigned, nil)
	}
	if assignment.OperatorGrn != authority.Assignee.String() {
		return 0, time.Time{}, agent.ErrNotAssigned
	}
	now, err := q.Now(ctx)
	if err != nil {
		return 0, time.Time{}, storageError(err, "read clock", nil, nil)
	}
	if !now.Time.Before(authority.GrantExpiresAt) {
		return 0, time.Time{}, agent.ErrAuthorityExpired
	}
	return int(assignment.Epoch), now.Time, nil
}

func (s *Store) GetExecution(ctx context.Context, agentGRN grn.GRN) (*agent.Execution, error) {
	row, err := s.q.GetExecution(ctx, agentGRN.String())
	if err != nil {
		return nil, storageError(err, "get execution", agent.ErrAgentNotFound, nil)
	}
	mode, err := agent.ParseMode(row.Mode)
	if err != nil {
		return nil, errorx.Wrap(err, "stored execution mode", errorx.KindInternal)
	}
	e := &agent.Execution{
		Agent:   agentGRN,
		Mode:    mode,
		Lineage: lineageOf(row.Lineage),
		Latest:  activationIDOf(row.LatestActivationID),
	}
	if id := activationIDOf(row.ActivationID); id != nil {
		generation, err := agent.ParseGeneration(row.CurrentGeneration.String)
		if err != nil {
			return nil, errorx.Wrap(err, "stored generation", errorx.KindInternal)
		}
		e.Current = &agent.CurrentActivation{ID: *id, Generation: generation}
	}
	return e, nil
}

func (s *Store) Introspect(ctx context.Context, agentGRN grn.GRN, c agent.Credential) (*agent.Snapshot, error) {
	row, err := s.q.Introspect(ctx, db.IntrospectParams{
		AgentGrn:  agentGRN.String(),
		Serial:    c.Serial,
		NotBefore: stamp(c.NotBefore),
		NotAfter:  stamp(c.NotAfter),
	})
	if err != nil {
		return nil, storageError(err, "introspect", agent.ErrAgentNotFound, nil)
	}
	mode, err := agent.ParseMode(row.Mode)
	if err != nil {
		return nil, errorx.Wrap(err, "stored execution mode", errorx.KindInternal)
	}
	snapshot := &agent.Snapshot{Mode: mode, CredentialCurrent: row.CredentialCurrent}
	if row.Assignee.Valid {
		assignee, err := grn.Parse(row.Assignee.String)
		if err != nil {
			return nil, errorx.Wrap(err, "stored assignee", errorx.KindInternal)
		}
		snapshot.Assignee, snapshot.Epoch = &assignee, int(row.Epoch.Int32)
	}
	if id := activationIDOf(row.ActivationID); id != nil {
		generation, err := agent.ParseGeneration(row.CurrentGeneration.String)
		if err != nil {
			return nil, errorx.Wrap(err, "stored generation", errorx.KindInternal)
		}
		snapshot.Current = &agent.CurrentActivation{ID: *id, Generation: generation}
	}
	return snapshot, nil
}

func (s *Store) CredentialCurrent(ctx context.Context, agentGRN grn.GRN, c agent.Credential) (bool, error) {
	current, err := s.q.CredentialCurrent(ctx, credentialParams(agentGRN, c))
	if err != nil {
		return false, storageError(err, "credential current", nil, nil)
	}
	return current, nil
}

func credentialParams(agentGRN grn.GRN, c agent.Credential) db.CredentialCurrentParams {
	return db.CredentialCurrentParams{
		AgentGrn:  agentGRN.String(),
		Serial:    c.Serial,
		NotBefore: stamp(c.NotBefore),
		NotAfter:  stamp(c.NotAfter),
	}
}

func stamp(t time.Time) pgtype.Timestamptz {
	return pgtype.Timestamptz{Time: t, Valid: true}
}

func pgUUID(u uuid.UUID) pgtype.UUID {
	return pgtype.UUID{Bytes: u, Valid: true}
}

func optionalUUID(u *uuid.UUID) pgtype.UUID {
	if u == nil {
		return pgtype.UUID{}
	}
	return pgUUID(*u)
}

func lineageOf(u pgtype.UUID) *agent.Lineage {
	if !u.Valid {
		return nil
	}
	l := agent.Lineage(u.Bytes)
	return &l
}

func activationIDOf(u pgtype.UUID) *agent.ActivationID {
	if !u.Valid {
		return nil
	}
	id := agent.ActivationID(u.Bytes)
	return &id
}

func optionalText(s *string) pgtype.Text {
	if s == nil {
		return pgtype.Text{}
	}
	return pgtype.Text{String: *s, Valid: true}
}
